    return
  }

  sendJson(res, 404, { error: `接口不存在：${method} ${pathname}` })
}

// ---------------------------------------------------------------- 启动

const server = createServer((req, res) => {
  const startedAt = Date.now()
  const url = new URL(req.url ?? '/', `http://${req.headers.host ?? `${HOST}:${PORT}`}`)
  res.on('finish', () => {
