    if (!res.headersSent) sendJson(res, 500, { error: `服务器内部错误：${error.message}` })
    else res.end()
  })
})

server.listen(PORT, HOST, () => {
  console.log(`[demo-app] 小商城已启动：http://${HOST}:${PORT}`)
})

export { server, PRODUCTS }
"}

